"use client";
import {useEffect,useState} from "react";import PageTitle from "@/composants/ui/PageTitle";import Section from "@/composants/ui/Section";import serviceSignalement from "@/services/ServiceSignalement";
export default function Page(){const[items,setItems]=useState([]);async function refresh(){setItems((await serviceSignalement.getAll()).filter(i=>i.type==="probleme_paiement"))}useEffect(()=>{refresh()},[]);async function act(id,status){await serviceSignalement.update(id,status,"Décision financière enregistrée.");await refresh()}return <div className="space-y-8"><PageTitle title="Litiges de paiement" description="Les signalements financiers sont routés directement vers cet espace."/><Section title={`${items.length} dossier(s)`}>{items.length===0?<p className="text-sm text-slate-600">Aucun litige de paiement.</p>:<div className="space-y-3">{items.map(i=><div key={i.id} className="rounded-2xl border border-slate-200 bg-slate-50 p-5"><p className="font-black">Signalement #{i.id}</p><p className="mt-2 text-sm text-slate-700">{i.description}</p><div className="mt-4 flex gap-2"><button onClick={()=>act(i.id,"resolu")} className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-bold text-white">Résoudre</button><button onClick={()=>act(i.id,"rejete")} className="rounded-lg border border-slate-300 px-3 py-2 text-xs font-bold text-slate-700">Rejeter</button></div></div>)}</div>}</Section></div>}
